insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('culture', 'Start Here', NULL, 'Culture & Conduct', '[{"t":"p","x":"The 5 Pillars are how we think. The Doctrine is how we operate. The Redlines are what ends employment. Leaders included: lead by example."},{"t":"h2","x":"The 5 Pillars"},{"t":"table","head":["Pillar","In short"],"rows":[["Ownership Mentality","Own your tasks and outcomes. No excuses, no blame, finish what you start."],["Progress Over Perfection","Move and deliver fast, then improve on real feedback. Done beats drafted."],["Data-Driven Thinking","Decide on numbers and clear reasoning, not assumptions or feelings."],["Continuous Growth","Get a little better every week. Learn from mistakes, build better habits."],["Team Before Ego","Put team success above personal ego. No gossip, no politics, open to feedback."]]},{"t":"h2","x":"Company Doctrine"},{"t":"steps","ordered":false,"x":["Company comes first","Ownership over excuses","System over individuals","Loyalty and trust are earned","Discipline creates freedom","Data over assumption","Leaders lead by example","Improve every month","No toxic behavior","Build something bigger"]},{"t":"h2","x":"Redlines: zero tolerance"},{"t":"callout","tone":"warn","title":"Immediate termination","x":"Data betrayal · Player or financial misconduct · Theft or fraud · Unauthorized player handling · Security violations · Dishonesty with leadership · External business conflicts · Substance abuse on duty · Public defamation · Unauthorized contact with ex-staff."}]', '["V1.0","Everyone reads this first","Updated 17 Sep 2026"]', 'V1.0', 'ATL', 0, 'live', 'pillars doctrine redlines values conduct ownership integrity', 1);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('department-overview', 'Start Here', NULL, 'Department Overview', NULL, NULL, 'V1.0', 'ATL', 0, 'pending', 'mission scope brands tiers roles about', 2);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('team-structure', 'Start Here', NULL, 'Team Structure', NULL, NULL, 'V1.0', 'ATL', 0, 'pending', 'org chart headcount roles about', 3);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('case-study-logging', 'SOP Book', 'Governance & Integrity', 'Case Study Logging', '[{"t":"p","x":"**Applies to:** All VIP CS; Senior and ATL review"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Capture real incidents into the Case Study Library so the team learns from cases, not only from procedure."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Any notable operational error, player abuse or exploit, or provider/system issue worth learning from."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Real incidents only. Never invent a case to fill a category.","Role titles only. No staff or player names, no player IDs or UIDs.","\"What we learn\" is the point of the row; keep it to what a reader should do differently."]},{"t":"h2","x":"4. Procedure (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Spot a case worth logging","On a notable incident","Real incident with a lesson; skip the trivial","Chat, BO, reports"],["2","Categorise and rate severity","After spotting","Operational Error / Player Abuse-Exploit / Provider-System Issue; severity Critical/High/Medium/Low","Category definitions"],["3","Write the case row","After categorising","What Happened, Why It Happened, What We Learn, Rule or SOP it maps to; role titles only","Case Study Library"],["4","Link the full write-up","If detailed","Summary in the library, full write-up in a Lark Doc, link in Reference","Lark Docs"],["5","Review and fold back","Periodically","Senior/ATL review; if a case reveals an SOP gap, feed it to the SOP owner","SOP Book"]]},{"t":"h2","x":"5. Guards"},{"t":"list","x":["Real only; no names or UIDs; the lesson is the point."]},{"t":"h2","x":"6. Remarks"},{"t":"list","x":["Source reports stay credited to their original authors. The library is the summary, not a replacement."]}]', '["C9MYR-RTN-SOP-GOV02","V1.0","Governance / Learning","Owner: VIP RTN","Updated 5 Sep 2026"]', 'V1.0', 'ATL', 0, 'live', 'incident exploit lesson severity case study', 4);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('reporting-data-integrity', 'SOP Book', 'Governance & Integrity', 'Reporting & Data Integrity', NULL, NULL, 'V1.0', 'ATL', 0, 'planned', NULL, 5);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('escalation', 'SOP Book', 'Governance & Integrity', 'Escalation', NULL, NULL, 'V1.0', 'ATL', 0, 'planned', NULL, 6);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('process-landing-layer', 'SOP Book', 'Governance & Integrity', 'Process Landing Layer', '[{"t":"p","x":"**Applies to:** ATL, Senior, process owners"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Make the SOP Book a working system, not a document set. These five tools cover Methods 5, 7, 8, 9 and 10, so every SOP is validated, trained, monitored, reviewed and archived."},{"t":"h2","x":"2. How the book maps to the 10 methods"},{"t":"table","head":["Method","Where it lives in the book"],"rows":[["1 Design team, owner","Owner field on every SOP"],["2 Identify high-value SOPs","SOP coverage map (priority order)"],["3 Benchmark, co-create","Sourcing thin SOPs from the top performer"],["4 Write the SOP (4 elements)","The SOP template"],["5 Validate, trial-run","Validation checklist (below)"],["6 Manager confirm, release","Sign-off + effective date on release"],["7 Train, everyone executes","Training checklist (below)"],["8 Monitor, check","Monitoring metrics (below)"],["9 Review, iterate","Review log (below)"],["10 Archive, bank knowledge","Archive standard (below)"]]},{"t":"h2","x":"3. Validation checklist (Method 5)"},{"t":"p","x":"Before release, trial-run on 1-2 people for 1-2 weeks, then confirm:"},{"t":"list","x":["Are the steps clear enough for a normal person to follow?","Are the tools named and usable?","Do the exceptions have a plan?","Feedback collected and fixed; re-tested until smooth."]},{"t":"p","x":"A process is tested out, not designed out."},{"t":"h2","x":"4. Training checklist (Method 7)"},{"t":"p","x":"Three stages, each with a gate:"},{"t":"list","x":["Awareness: read the SOP / attend the briefing (knows what it is).","Skill: drill + assessment passed (can do it).","Willingness: benefit explained, questions answered (wants to use it)."]},{"t":"p","x":"Landing: SOP online + on the daily task checklist with KPI."},{"t":"h2","x":"5. Monitoring metrics (Method 8)"},{"t":"table","head":["Metric","Formula","Cadence","Owner"],"rows":[["Execution rate","SOP-followed / total","Weekly","Process owner"],["Error rate","Not-followed / total","Monthly","Ops"],["Effect","Problems solved / effectiveness","Quarterly","Management"]]},{"t":"p","x":"Correction: not-followed to coach to warn; problem found to feedback to improve. A process with no check is a decoration on the wall."},{"t":"h2","x":"6. Review log (Method 9)"},{"t":"p","x":"Trigger a review on: schedule (quarterly), a problem, or a business change. Ask three questions:"},{"t":"list","x":["Is it still solving the problem?","Is it simple enough?","Does it need updating?"]},{"t":"p","x":"Bump the version and record what changed. Yesterday''s process can be today''s problem."},{"t":"h2","x":"7. Archive standard (Method 10)"},{"t":"list","x":["Unified format (this template), clear directory, quick to find (indexed), permissioned (who views, who edits).","For new hires: the docs are required reading, the teaching material, and an exam item.","Keep the version history."]},{"t":"p","x":"Documents are the department''s cheapest trainer."},{"t":"h2","x":"8. Remarks"},{"t":"p","x":"This layer is what makes the SOP Book read as above-expectation: it shows the process is designed, validated, trained, watched, and improved, not just written."}]', '["C9MYR-RTN-SOP-GOV03","V1.0","Governance","Owner: ATL","Updated 5 Sep 2026"]', 'V1.0', 'ATL', 0, 'live', NULL, 7);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('grace', 'SOP Book', 'Money Control & Bonuses', 'Grace Period List', '[{"t":"p","x":"**Applies to:** VIP CS, all brands"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Filter eligible Grace Period players and send targeted Internal Mail to drive re-engagement before the grace period expires."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Applies to the daily Grace Period send on Monday, Tuesday, Thursday and Friday, across all brands. Monday and Tuesday are primary sends; Thursday and Friday are follow-ups."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Match the send to the scheduled day: Mon/Tue primary, Thu/Fri follow-up. No Grace send on Wed/Sat/Sun.","SMS is sent by Retention Team Admin, not VIP CS. VIP CS prepares the list only.","Invalid players get IM + Push only. No SMS, no bonus mention.","A Grace bonus is issued only when SW x 20% reaches the minimum eligible tier, and SW is updated the same day before issuance.","Verify player status before sending; skip anyone who already deposited or changed tier."]},{"t":"h2","x":"4. Sending Schedule"},{"t":"table","head":["Day","Action","Send Type","Notes"],"rows":[["Monday","Send Grace Period Player IM","Primary Send, List A","Grace Period Players (have NOT achieved monthly threshold). Pass eligible list to Admin for SMS."],["Tuesday","Send Potential Player IM","Primary Send, List B","Potential Players (have achieved or exceeded monthly threshold). Pass eligible list to Admin for SMS."],["Wednesday","No Grace Period IM required","-","Rest day for this task"],["Thursday","Follow-Up, Monday List (List A)","Follow-Up Send","Follow up on Monday''s list. Target: non-responders and non-converts."],["Friday","Follow-Up, Tuesday List (List B)","Follow-Up Send","Follow up on Tuesday''s list. Target: non-responders and non-converts."],["Saturday","No Grace Period IM required","-","Rest day for this task"],["Sunday","No Grace Period IM required","-","Rest day for this task"]]},{"t":"h2","x":"5. Eligibility: Valid vs Invalid"},{"t":"table","head":["Status","Definition","Action"],"rows":[["**Grace Period Player** (Mon + Thu)","Has NOT achieved the monthly deposit threshold, still within the grace window.","IM + Push. Pass eligible list to Admin for SMS. Goal: activate deposit."],["**Potential Player** (Tue + Fri)","HAS achieved or exceeded the monthly threshold.","IM + Push. Pass eligible list to Admin for SMS. Goal: maintain engagement and loyalty."]]},{"t":"h2","x":"6. Procedure (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Receive the Grace Period database from Retention Team (Admin)","Task start, on a scheduled send day (Mon/Tue/Thu/Fri)","Via Team Engagement File > Handover Tab; Admin provides the daily data, VIP CS extracts","Team Engagement File"],["2","Copy the database, paste into Customer Approaching Lark Base > Grace Period (Day)","After receiving","Paste values only, to protect formulas","Lark Base"],["3","Apply filters to separate Valid and Invalid by brand and status","After paste","Per Section 5 (Grace Period Player vs Potential Player)","Lark Base"],["4","Move filtered data to the Engagement Tab under the Grace Period column","After filtering","Each player under the correct brand column","Lark Base"],["5","VALID players: pass username list to Admin for SMS; send IM + Push","On send","SMS is Admin-side, not VIP CS","Lark / BO"],["6","INVALID players: send IM + Push only","On send","No SMS, no bonus mention; engagement only","Lark / BO"],["7","Update the QA Record","After all IM sent","Attach a BO screenshot as proof","Lark Base"]]},{"t":"h2","x":"7. Bonus Logic: Grace Period Deposit Challenge"},{"t":"p","x":"**Activation rule:** a bonus may only be issued when 20% of the customer''s Secret Wallet (SW x 20%) reaches the minimum eligible threshold. Match that figure to the highest eligible tier. SW must be updated the same day before issuance."},{"t":"table","head":["Tier","Deposit","Free Bonus","SW Cap"],"rows":[["T3","RM 100","RM 18","SW x 20%"],["T3","RM 200","RM 28","SW x 20%"],["T3","RM 300","RM 38","SW x 20%"],["T3","RM 500","RM 58","SW x 20% (T3 cap)"],["TV","RM 600","RM 68","SW x 20%"],["TV","RM 700","RM 78","SW x 20%"],["TV","RM 800","RM 88","SW x 20%"],["TV","RM 900","RM 98","SW x 20%"],["TV","RM 1,000","RM 108","SW x 20% (TV cap)"]]},{"t":"p","x":"Withdrawable after 1x turnover. Offer applies to next-day deposits only, has a validity period, and starts when the customer confirms. Tag `Grace Active` when engaged, `Grace Converted` when deposited and claimed. Claim via Lark ticket, query `VVIP Grace Period`."},{"t":"h2","x":"8. Guards"},{"t":"list","x":["Empty list on a scheduled day: record it in the QA Record and inform the ATL. Never skip silently.","Never issue a Grace bonus above the SW x 20% cap.","Do not send to players who already deposited or whose tier changed."]},{"t":"h2","x":"9. Remarks"},{"t":"list","x":["Eligible (Valid) enters segmentation and can claim the Deposit Challenge; Invalid gets IM + Push only.","SW must be refreshed the same day before any sizing; a stale SW is not a valid base."]}]', '["C9MYR-RTN-SOP-D01","V1.1","Day Shift / VIP","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'bonus deposit grace expiry re-engage internal mail day shift', 8);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('birthday-bonus', 'SOP Book', 'Money Control & Bonuses', 'Birthday Bonus', '[{"t":"p","x":"**Applies to:** All VIP CS; ATL for high-value approval"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Reward eligible Tier 3 and Tier V players on their birthday with a controlled credit, once per year, sized to the player''s own value and never stacked with another reward."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Applies to all VIP CS on every brand. High-value cases (Total Deposit at or above RM 100,000) must be handled by the ATL or above. One claim per player per calendar year."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Has SW: deduct from SW, 1x turnover. No SW / deposit base: no SW deduction, 3x turnover.","Total Deposit at or above RM 100,000: ATL or above approval. CS cannot issue directly.","One claim per player per calendar year.","No guaranteed amount before the eligibility check.","No stacking with any other reward."]},{"t":"h2","x":"4. Procedure (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Pull today''s Tier 3 / Tier V birthday list","Task start","Birthday source available; Birthday Reward Claimed This Year = No","Birthday source, BO"],["2","Basic screening per player","Before sizing","Skip on any Yes: already claimed this year, risk/abuse tag, or same-day Reload/Compensation/LTV","BO"],["3","Confirm the calculation base","After screening","Has SW: SW base, deduct SW, 1x TO. No SW: Last Month Deposit base, no deduction, 3x TO","BO"],["4","Size the credit","After base set","Per Section 7 (SW base) or Section 8 (deposit base); match the highest eligible 8-ending amount within the cap; above Max use Max, below Floor use Floor","Bonus calc"],["5","Apply the ATL approval gate","Before issuing a high-value case","Total Deposit >= RM 100,000: ATL or above confirms value, claim history, risk tag, final amount; tag `Birthday Credit - ATL Reviewed`","Lark, ATL"],["6","Issue and record","On issuance","Mark Birthday Credit Rewarded; record tier, base, amount, TO, SW deduction (y/n), issued by, time; set Birthday Reward Claimed This Year = Yes","BO, QA Record"]]},{"t":"h2","x":"5. Step 1: Pull the Birthday List"},{"t":"list","x":["Pull today''s Tier 3 / Tier V birthday players.","The birthday source must be available.","Birthday Reward Claimed This Year must be No."]},{"t":"h2","x":"6. Step 2: Basic Screening"},{"t":"p","x":"Check each player one by one. Any Yes means skip."},{"t":"table","head":["Check","Yes","No"],"rows":[["Already claimed the birthday credit this year","Skip","Continue"],["Risk / abuse tag","Skip","Continue"],["Same-day Reload / Compensation / LTV reward","Skip","Continue"]]},{"t":"h2","x":"7. Step 3 and 4A: Confirm the Base, SW Base Calculation"},{"t":"table","head":["Player state","Base","SW deduction","Turnover"],"rows":[["Has Secret Wallet","SW base","Deduct from SW","1x"],["No SW / SW positive base","Last Month Deposit base","None","3x"]]},{"t":"table","head":["Tier","Formula","Max","TO","SW deduction"],"rows":[["Tier 3","SW balance x 25%","RM 888","1x","Yes"],["Tier V","SW balance x 30%","RM 1,688","1x","Yes"]]},{"t":"p","x":"Amount rule: the final birthday credit must be at or below the calculated SW amount. Match the highest eligible 8-ending amount within it. If above the Max, use the Max. Deduct the issued amount from SW."},{"t":"p","x":"Examples:"},{"t":"list","x":["Tier 3, SW 200: 200 x 25% = 50, final RM 48.","Tier 3, SW 500: 500 x 25% = 125, final RM 118.","Tier V, SW 400: 400 x 30% = 120, final RM 118.","Tier V, SW 4,000: 4,000 x 30% = 1,200, final RM 1,188."]},{"t":"h2","x":"8. Step 4B: Deposit Base Calculation (No SW)"},{"t":"table","head":["Tier","Formula","Floor","Max","TO","SW deduction"],"rows":[["Tier 3","Total Deposit x 0.1%","RM 38","RM 188","3x","No"],["Tier V","Total Deposit x 0.1%","RM 68","RM 388","3x","No"]]},{"t":"p","x":"Amount rule: use Last Month Deposit as the reference. Match the highest eligible amount that does not exceed the calculated amount. If the calculated amount is below the Floor, use the Floor. No SW deduction."},{"t":"p","x":"Source examples (as provided):"},{"t":"list","x":["Tier 3, deposit 10,000: 0.1% = RM 10, final RM 18.","Tier 3, deposit 100,000: 0.1% = RM 100, final RM 108.","Tier V, deposit 10,000: 0.1% = RM 10, final RM 38.","Tier V, deposit 200,000: 0.1% = RM 200, final RM 208."]},{"t":"callout","tone":"warn","title":"Open item","x":"Source conflict, unresolved: the Tier 3 example (calculated RM 10, final RM 18) sits below the stated Floor of RM 38, and the final exceeds the calculated amount. Do not issue a deposit-base Tier 3 credit for a low deposit until the ATL confirms the floor and the low-deposit case."},{"t":"h2","x":"9. Step 5: ATL Approval Gate"},{"t":"p","x":"If Total Deposit is at or above RM 100,000:"},{"t":"list","x":["Must be handled by the ATL or above. CS cannot issue directly.","The ATL confirms player value, claim history, risk tag and the final credit amount.","Tag as `Birthday Credit - ATL Reviewed`."]},{"t":"h2","x":"10. Step 6: Issue and Record"},{"t":"p","x":"After issuing:"},{"t":"list","x":["Mark Birthday Credit Rewarded.","Record: tier, calculation base, amount, TO, SW deduction (yes/no), issued by, issued time.","Update Birthday Reward Claimed This Year = Yes."]},{"t":"h2","x":"11. Guards"},{"t":"list","x":["Any screening Yes means skip the player.","High-value cases (Total Deposit >= RM 100,000) are never issued by CS directly.","The deposit-base Tier 3 low-deposit case is unresolved (Section 8 conflict flag); do not issue until the ATL confirms.","No stacking with any other reward; no guaranteed amount before the eligibility check."]},{"t":"h2","x":"12. Remarks"},{"t":"list","x":["The floor/low-deposit conflict in Section 8 is still open; confirm with the ATL before relying on it.","SW must be updated the same day before any SW-base sizing."]}]', '["C9MYR-RTN-SOP-BD01","V1.1","Bonus / Engagement","Owner: VIP RTN / ATL","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'birthday bonus', 9);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('weekend-campaign', 'SOP Book', 'Money Control & Bonuses', 'Weekend Campaign', '[{"t":"p","x":"**Applies to:** VIP CS, all brands"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Run the weekend-only campaign every Saturday and Sunday. Three components: Ang Bao, Free Spin, and Deposit Challenge (under testing). Each has distinct tier and platform targeting."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Saturday and Sunday only. Issuing any component on a weekday is a process violation."},{"t":"table","head":["Day","Active","Ang Bao","Free Spin","Deposit Challenge"],"rows":[["Mon to Fri","No","-","-","-"],["Saturday","Yes","Active","Active","Under testing"],["Sunday","Yes","Active","Active","-"]]},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["The whole campaign runs Saturday and Sunday only. A weekday issuance is a process violation.","Ang Bao is TC only; Free Spin is Zyra only. Never cross-issue.","Ang Bao tier split is strict: Normal (RM 2 to 8) Tier 3, Special (RM 8 to 18) Tier V.","Deposit Challenge is under testing. Confirm with ATL or TL before any issuance.","If a player''s tier is unclear, verify in the BO before issuing any weekend reward."]},{"t":"h2","x":"4. Component 1: Ang Bao (TC only)"},{"t":"table","head":["Type","Amount","Tier","Platform"],"rows":[["Normal Ang Bao","RM 2 to RM 8","Tier 3 only","TC"],["Special Ang Bao","RM 8 to RM 18","Tier V only","TC"]]},{"t":"list","x":["Tier 3 gets Normal only, Tier V gets Special only. Never cross-issue.","TC platform only. Not applicable on Zyra.","Weekend only."]},{"t":"h2","x":"5. Component 2: Free Spin (Zyra only) [DISCONTINUED]"},{"t":"p","x":"**Discontinued from September 2026. Do not issue Free Spin. Kept here for reference only.**"},{"t":"table","head":["Type","Spins","Tier","Platform"],"rows":[["Standard","20 Free Spins","Tier 3","Zyra"],["Enhanced","30 Free Spins","Tier V","Zyra"]]},{"t":"list","x":["Zyra brands only. Not applicable on TC.","Weekend only.","The tier split (20 vs 30 spins) and issuance method are no longer relevant; the component is discontinued (September 2026)."]},{"t":"h2","x":"6. Component 3: Deposit Challenge (UNDER TESTING)"},{"t":"p","x":"Do not implement without explicit ATL or TL sign-off. Reward structure confirmed; operational procedure pending."},{"t":"table","head":["Deposit","Extra Reward","Net Benefit (cumulative)"],"rows":[["RM 588","RM 38","RM 38"],["RM 1,008","RM 88","RM 126"],["RM 1,888","RM 188","RM 314"],["RM 3,088","RM 388","RM 702"],["RM 8,888","RM 1,288","RM 1,990"]]},{"t":"list","x":["The extra reward is added on top of the deposit.","Step-up is cumulative: a higher tier unlocks all lower tiers too. Example: deposit RM 1,888 gives RM 188 + RM 88 + RM 38 = RM 314 extra.","Platform, issuance method, eligible tiers and ticket query all pending TL confirmation."]},{"t":"h2","x":"7. Guards"},{"t":"list","x":["A weekday issuance of any component is a process violation.","Ang Bao (TC only) and Free Spin (Zyra only) are on different platforms; do not cross-issue.","Deposit Challenge is under testing; confirm with ATL or TL before any issuance.","If a player''s tier is unclear, verify in the BO before issuing."]},{"t":"h2","x":"8. Remarks"},{"t":"list","x":["Ang Bao tier split is strict: Normal (RM 2 to 8) Tier 3, Special (RM 8 to 18) Tier V.","Free Spin tier/spin distinction and issuance method are pending ATL / PIC confirmation."]}]', '["C9MYR-RTN-SOP-B01","V1.1","Bonus / Strategy","Owner: VIP RTN / ATL","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'angpao ang bao free spin deposit challenge saturday sunday', 10);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('bonus-issuance-approval', 'SOP Book', 'Money Control & Bonuses', 'Bonus Issuance & Approval', NULL, NULL, 'V1.0', 'ATL', 0, 'planned', NULL, 11);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('compensation', 'SOP Book', 'Money Control & Bonuses', 'Compensation', NULL, NULL, 'V1.0', 'ATL', 0, 'planned', NULL, 12);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('qa-record', 'SOP Book', 'Reporting & Data', 'QA Record', '[{"t":"p","x":"**Applies to:** All VIP CS"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Record documentary evidence of every completed outreach task, for accountability, quality assurance and shift tracking."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Applies after every outreach task, every shift. The QA Record must be updated immediately after each task, not accumulated to end of shift."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Update the QA Record immediately after each task, not at end of shift.","Never submit an entry without the required BO screenshot.","If a task was not done, record it as \"Not Completed\" with a brief reason. Never leave it blank.","Do not modify the date or category of a submitted record. Ask the ATL for corrections."]},{"t":"h2","x":"4. Trigger Events and Required Evidence"},{"t":"table","head":["Task","Trigger","Evidence"],"rows":[["Grace Period IM","After all Grace Period IM sent","BO screenshot of send confirmation"],["LTV IM","After all LTV IM sent","BO screenshot of send confirmation"],["VVIP Blast","After all VVIP IM sent","BO screenshot of send confirmation"],["Risk Push","After Push sent","BO screenshot of send confirmation"],["Top PNL","After list compiled + bonus issued","Screenshot of list + Lark ticket reference"],["Top Deposit","After engagement complete","Screenshot of completed list"],["Internal Mail Blast","After each blast","BO screenshot of send confirmation"],["Telegram Approach","End of shift","Summary: total approached + conversions"],["LC Complaint Compensation","After bonus issued via complaint","Lark ticket reference (query `VVIP Complain player`)"]]},{"t":"h2","x":"5. Procedure (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Screenshot from the BO immediately after each task","Right after each task","Must clearly show the completion confirmation","BO"],["2","Open the Customer Approaching QA table in Lark Base","After screenshot","Correct table","Lark Base"],["3","Check if today''s date record exists; if not, create one","Before attaching","One parent QA record per calendar date","Lark Base"],["4","Attach the screenshot under the correct date entry","After the date record exists","Correct date and category, not the wrong one","Lark Base"],["5","Select the correct task category","While recording","Grace Period, LTV, VVIP Blast, Risk Push, Top PNL, Top Deposit, IM Blast, Telegram, LC Complaint","Lark Base"],["6","Record validity status: Valid or Invalid","While recording","If both, record both counts separately","Lark Base"],["7","Record the total players approached this shift","While recording","Feeds output reporting and performance","Lark Base"],["8","Confirm entries are saved before the next task","Before next task","Saved and verified","Lark Base"],["9","Complete and submit all QA records before shift end","End of shift","Incomplete records break the Output Report","Lark Base"]]},{"t":"h2","x":"6. Guards"},{"t":"list","x":["Never submit an entry without the required BO screenshot.","Incomplete QA records break the Output Report; complete all before shift end.","Do not modify a submitted record''s date or category; route corrections through the ATL."]},{"t":"h2","x":"7. Remarks"},{"t":"list","x":["Update immediately after each task, not at end of shift.","If a task was not done, record it as \"Not Completed\" with a brief reason."]}]', '["C9MYR-RTN-SOP-R01","V1.1","Reporting","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'evidence screenshot proof quality reporting', 13);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('output-report', 'SOP Book', 'Reporting & Data', 'Output Report', '[{"t":"p","x":"**Applies to:** All VIP CS"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Compile and submit a complete shift performance summary by copying player engagement data from Lark Base into the VIP RTN CS Output file."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"End of every shift, per PIC. Only your own records, only today''s date."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Always apply both filters (Date today AND PIC you) before copying. Missing one gives wrong or incomplete data.","Paste values only, no formatting or formulas.","Each column pastes separately via its own filter cycle. Do not combine.","If a column has no data (e.g. no SMS today), leave it blank. Do not paste a zero or placeholder."]},{"t":"h2","x":"4. Procedure: Pull Data from Lark Base (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Open Customer Approaching Lark Base > Output - Table","Task start","Holds all engagement records for the month","Lark Base"],["2","Apply two filter conditions together","Before copying","Both must be active before copying","Lark Base"],["2a","Set Date is today","With step 2","Remove any other date filter","Lark Base"],["2b","Set PIC is your name","With step 2","Do not copy another staff member''s data","Lark Base"],["3","Copy each engagement column one at a time","After filtering","Livechat, Internal Mail, Push, SMS, each separately","Lark Base"]]},{"t":"p","x":"**Columns and destinations:** Livechat, Internal Mail, Push Notification, SMS, each into its matching column in the VIP RTN CS Output."},{"t":"h2","x":"5. Procedure: Paste into CS Output (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Open the VIP RTN CS Output file","After pulling data","Correct file","VIP RTN CS Output"],["2","Select today''s date tab (e.g. `11/05`)","After opening","Each day has its own tab","VIP RTN CS Output"],["3","On Row 6 (filter row), click the Livechat column filter","Before pasting","Correct column filter","VIP RTN CS Output"],["4","Clear All in the filter dropdown","After clicking filter","Prevents mixing data types","VIP RTN CS Output"],["5","Select only Livechat, confirm","After Clear All","Table shows Livechat rows only","VIP RTN CS Output"],["6","Paste the Livechat data","After filtering","Paste values only","VIP RTN CS Output"],["7","Repeat steps 3 to 6 for Internal Mail, Push, SMS","Per remaining column","One filter pass per column","VIP RTN CS Output"],["8","Clear the Row 6 filter to restore the full view","After all columns","Verify data sits under the right column and row","VIP RTN CS Output"],["9","Update the QA Record after submitting","After submit","Attach a screenshot of the completed Output tab","Lark Base"]]},{"t":"h2","x":"6. Guards"},{"t":"list","x":["Missing either filter (Date today, PIC you) gives wrong or incomplete data.","Do not change the Row 6 sort order after pasting; it displaces data.","Leave an empty column blank; never paste a zero or placeholder."]},{"t":"h2","x":"7. Remarks"},{"t":"list","x":["Paste values only, no formatting or formulas.","Each column pastes separately via its own filter cycle."]}]', '["C9MYR-RTN-SOP-R02","V1.1","Reporting","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'shift summary reporting cs output livechat count', 14);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('roi-table', 'SOP Book', 'Reporting & Data', 'ROI Table', '[{"t":"p","x":"**Applies to:** VIP CS, assigned brands"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Track deposit and withdrawal amounts for bonus-claiming players across a 3-day window before and after the bonus claim date, to measure ROI per outreach campaign."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Applies to every player who claimed a bonus in the current month, on both TC and Zyra."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["The claim date is excluded from both windows. Before = claim minus 3 to claim minus 1. After = claim plus 1 to claim plus 3.","TC: approved deposits only (exclude pending/rejected); DP and WD are on separate tabs. Zyra: DP and WD are in the same overview.","If a player has no DP/WD in a range, record 0. Do not leave it blank.","Complete all four columns for one player before moving to the next.","TC uses username; Zyra uses UID."]},{"t":"h2","x":"4. The Four Tracked Columns"},{"t":"p","x":"The claim date itself is never included in either window. Before = up to claim minus 1. After = from claim plus 1."},{"t":"table","head":["Column","Measures","Range (claim 3 May example)"],"rows":[["3D Before DP","Approved deposits, 3 days before","30 Apr to 2 May"],["3D Before WD","Withdrawals, 3 days before","30 Apr to 2 May"],["3D After DP","Approved deposits, 3 days after","4 May to 6 May"],["3D After WD","Withdrawals, 3 days after","4 May to 6 May"]]},{"t":"callout","tone":"info","x":"Confirmed 10 Sep 2026: the window is 3 days each side. Before = claim minus 3 to claim minus 1; After = claim plus 1 to claim plus 3. The 2-day reading in an earlier source example was wrong."},{"t":"h2","x":"5. Procedure: Filter the ROI Table (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Open Customer Approaching File > ROI Table","Task start","All players who claimed a bonus this month","Customer Approaching File"],["2","Apply two conditions","Before selecting players","Both active","Customer Approaching File"],["2a","Brand is your group''s brand(s)","With step 2","e.g. LPK for LPK777","Customer Approaching File"],["2b","Bonus Amount is not empty","With step 2","Removes players who have not claimed","Customer Approaching File"],["3","Identify the four columns to fill","After filtering","3D Before DP, 3D Before WD, 3D After DP, 3D After WD","Customer Approaching File"],["4","Copy the username of each player with any empty tracked column","After identifying","Those need BO lookup","Customer Approaching File"]]},{"t":"h2","x":"6. Procedure: TC Gaming Retrieval (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Customer Search, paste the username","Per player","One player at a time, exact match","TC Gaming BO"],["2","Open the profile, go to Deposit Record","After search","Correct player","TC Gaming BO"],["3","Confirm the claim date in the ROI Table","Before setting ranges","Match the ROI Table","Customer Approaching File"],["4","Set the deposit date range to 3 days before claim","After confirming date","claim minus 3 to claim minus 1","TC Gaming BO"],["5","Record total approved deposits into 3D Before DP","After range set","Approved only, exclude pending/rejected","Customer Approaching File"],["6","Go to Withdrawal Record","After DP recorded","Correct tab","TC Gaming BO"],["7","Same before-range, record total withdrawals into 3D Before WD","After opening WD","Same range","Customer Approaching File"],["8","Set the range to 3 days after claim","After before-window done","claim plus 1 to claim plus 3","TC Gaming BO"],["9","Record total approved deposits into 3D After DP","After range set","Approved only","Customer Approaching File"],["10","Same after-range, record total withdrawals into 3D After WD","After DP recorded","Same range","Customer Approaching File"],["11","Repeat for every player","Until list clear","Complete all four columns per player before moving on","Customer Approaching File"]]},{"t":"h2","x":"7. Procedure: Zyra Retrieval (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Betting Record > User Betting Record Overview","Per player","Correct BO path","Zyra BO"],["2","Paste the UID (not username)","After opening","Verify it matches the ROI Table","Zyra BO"],["3","Confirm the claim date in the ROI Table","Before setting ranges","Match the ROI Table","Customer Approaching File"],["4","Set range to 3 days before claim, Search","After confirming date","claim minus 3 to claim minus 1","Zyra BO"],["5","Read Deposit and Withdrawal from the same overview","After search","No tab navigation needed","Zyra BO"],["6","Record Deposit into 3D Before DP, Withdrawal into 3D Before WD","After reading","Correct columns","Customer Approaching File"],["7","Change range to 3 days after claim, Search","After before-window done","claim plus 1 to claim plus 3","Zyra BO"],["8","Record Deposit into 3D After DP, Withdrawal into 3D After WD","After search","Correct columns","Customer Approaching File"],["9","Repeat for every player","Until list clear","All four columns per player","Customer Approaching File"]]},{"t":"h2","x":"8. Guards"},{"t":"list","x":["Always confirm the claim date in the ROI Table before setting any BO date range.","If a player has no DP/WD in a range, record 0. Do not leave blank.","Complete all four columns for one player before the next, to avoid cross-referencing errors."]},{"t":"h2","x":"9. Remarks"},{"t":"list","x":["TC: DP and WD are on separate tabs, approved amounts only. Zyra: both are in the same overview.","The claim date is excluded from both windows."]}]', '["C9MYR-RTN-SOP-R03","V1.1","Reporting","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'deposit withdrawal 3 day before after roi bonus claim', 15);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('ltv', 'SOP Book', 'Engagement Outreach', 'LTV List', '[{"t":"p","x":"**Applies to:** VIP CS, all brands"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Approach selected LTV players for targeted retention via Internal Mail. The Top 70 LTV pool is divided into 10 players per day, Monday to Sunday."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Applies daily. Selection is pulled every Monday by Retention Team Admin from the FTV Top 1 to 70 pool, LTV of 7 or more, Tier 3 and Tier V only."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Daily quota is exactly 10. Never exceed, never carry over.","Match today''s database to today''s day. Never borrow another day''s batch, even if today''s list is empty.","SW x 40% is the hard cap. A bonus above it cannot be issued; SW must be updated the same day before issuance.","Player must engage before issuance. Contact precedes deposit.","Invalid players: IM + Push only, no SMS, no bonus mention. SMS is Admin-side."]},{"t":"h2","x":"4. Day-of-Week Database"},{"t":"table","head":["Day","Database","Daily quota"],"rows":[["Monday","Players 1 to 10","10"],["Tuesday","Players 11 to 20","10"],["Wednesday","Players 21 to 30","10"],["Thursday","Players 31 to 40","10"],["Friday","Players 41 to 50","10"],["Saturday","Players 51 to 60","10"],["Sunday","Players 61 to 70","10"]]},{"t":"h2","x":"5. Eligibility: Valid vs Invalid"},{"t":"table","head":["Status","Definition","Action"],"rows":[["**Valid**","Not yet given this week''s LTV reward, no Daily P&L reward this week, SW sufficient (bonus <= SW x 40%).","Pass username list to Admin for SMS. VIP CS sends IM + Push. Goal: push to VIP Live Chat."],["**Invalid**","Already got this week''s LTV or Daily P&L, SW insufficient, or outside segmentation.","IM + Push only. No SMS, no bonus mention. Goal: engagement only."]]},{"t":"h2","x":"6. Procedure (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Open Team Engagement File > Handover Tab; locate today''s 10-player batch","Task start","Use today''s exact day; do not pull another day''s batch","Team Engagement File"],["2","Copy today''s 10 entries","After locating","Do not exceed the 10-player quota","Team Engagement File"],["3","Paste into Customer Approaching Lark Base > LTV (Day)","After copy","Paste values only","Lark Base"],["4","Deduplicate: remove anyone who already got Daily P&L or this week''s LTV","After paste","If under 10 remain, fill down the ranking","Lark Base"],["5","Pre-check per player: not yet given this week, currently active, SW sufficient","After dedup","All three must pass","Lark Base"],["6","SW check: bonus <= SW x 40%","During pre-check","Over 40% of SW means Invalid","Lark Base"],["7","Open with a greeting and observe; active: issue, cold: can delay","On contact","Player must engage before issuance","Livechat / Telegram"],["8","Valid: pass username list to Admin for SMS; send IM + Push","On send","SMS is Admin-side","Lark / BO"],["9","Invalid: IM + Push only, no SMS, no bonus mention","On send","Engagement only","Lark / BO"],["10","On target: submit Lark ticket (query `VVIP LTV 70 BONUS`) with username, bonus amount, conversation screenshot; tick Claimed","On issuance","Complete all ticket fields","Lark Base"],["11","Tag `Weekly LTV Rewarded (Week XX)`","After claim","Use the correct week number","Lark Base"],["12","Update the QA Record","After all IM and issuance","Attach a BO screenshot","Lark Base"]]},{"t":"h2","x":"7. Bonus Tier Ladder"},{"t":"p","x":"Rule: bonus must be <= SW x 40%. Same-day SW update mandatory before issuance."},{"t":"table","head":["LTV","Free Bonus","","LTV","Free Bonus"],"rows":[["2,000","RM 28","","12,000","RM 138"],["3,000","RM 38","","13,000","RM 158"],["4,000","RM 58","","14,000","RM 168"],["5,000","RM 68","","15,000","RM 178"],["6,000","RM 78","","16,000","RM 188"],["7,000","RM 88","","17,000","RM 198"],["8,000","RM 98","","18,000","RM 208"],["9,000","RM 108","","19,000","RM 218"],["10,000","RM 118","","20,000","RM 228"],["11,000","RM 128","",">= 21,000","RM 288 (cap)"]]},{"t":"h2","x":"8. Guards"},{"t":"list","x":["Empty list today: report to the ATL. Do not borrow another day''s batch.","Never exceed the 10-player quota, never carry over.","Never issue a bonus above the SW x 40% hard cap."]},{"t":"h2","x":"9. Remarks"},{"t":"list","x":["VIP CS prepares the list; Retention Team Admin sends the SMS.","SW x 40% is the hard cap. A bonus above it cannot be issued."]}]', '["C9MYR-RTN-SOP-D02","V1.1","Day Shift / VIP","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'bonus loyalty lifetime value top 70 retention', 16);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('pnl', 'SOP Book', 'Engagement Outreach', 'Top PNL', '[{"t":"p","x":"**Applies to:** VIP CS, all brands"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Identify the top 10 highest-loss players from today''s data and issue tiered Free Bonus compensation via the Daily P&L ladder, subject to the SW x 40% rule."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Night shift only, daily at 8:00 PM. Export and filter the namelist from 7:00 PM; start engagement at 8:00 PM after the data is relatively stable. Target the top 10 by daily P&L."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Night shift only. Export and filter from 7:00 PM; engage from 8:00 PM after data is stable.","SW x 40% is the absolute hard cap. Same-day SW update is mandatory before issuance.","Monthly P&L must be negative. If the player is monthly profitable, the bonus cannot be issued (over-issuance exception).","Daily P&L must be negative (player lost today).","Sort Total P&L A to Z; highest-loss players sit at the top."]},{"t":"h2","x":"4. Eligibility Screening (all must pass)"},{"t":"table","head":["Check","Pass condition","Fail action"],"rows":[["Daily P&L direction","Negative (player lost today)","Positive, SKIP"],["Today''s reward","Not yet claimed","Already claimed, SKIP"],["Secret Wallet","Bonus <= SW x 40%","Over cap, cannot issue"],["Monthly P&L direction","Monthly P&L negative","Monthly profitable, cannot issue"]]},{"t":"h2","x":"5. Daily P&L Bonus Ladder"},{"t":"p","x":"Rule: bonus <= SW x 40%. Same-day SW update mandatory. Claim via Lark ticket, query `VVIP TOP P&L BONUS`."},{"t":"table","head":["Daily loss","Free Bonus","","Daily loss","Free Bonus"],"rows":[["RM 1,000","RM 18","","RM 11,000","RM 128"],["RM 2,000","RM 28","","RM 12,000","RM 138"],["RM 3,000","RM 38","","RM 13,000","RM 158"],["RM 4,000","RM 58","","RM 14,000","RM 168"],["RM 5,000","RM 68","","RM 15,000","RM 178"],["RM 6,000","RM 78","","RM 16,000","RM 188"],["RM 7,000","RM 88","","RM 17,000","RM 198"],["RM 8,000","RM 98","","RM 18,000","RM 208"],["RM 9,000","RM 108","","RM 19,000","RM 218"],["RM 10,000","RM 118","","RM 20,000","RM 228"],["","","",">= RM 21,000","RM 288 (cap)"]]},{"t":"h2","x":"6. Procedure: TC Gaming Platform (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Go to Report Management > Player Analysis","Task start","Correct BO path","TC Gaming BO"],["2","Select today''s date, confirm it displays","After opening","Today''s date only","TC Gaming BO"],["3","Search and wait for data to fully load","Before export","Do not export early","TC Gaming BO"],["4","Export the Excel report","After full load","Save to the designated folder","TC Gaming BO"],["5","Open CS SORTING FILE, paste into the correct brand sheet","After export","Correct brand sheet","CS SORTING FILE"],["6","Under Member Label, filter to VVIP only","After paste","Remove non-VVIP","CS SORTING FILE"],["7","Sort Total P&L A to Z (lowest first)","After filtering","Biggest losses at top","CS SORTING FILE"],["8","Copy the first 10 usernames","After sort","Top 10 priority","CS SORTING FILE"],["9","Paste into Customer Approaching File > Top 10 P&L (Night), correct brand","After copy","Correct brand column","Customer Approaching File"],["10","Run the Section 4 eligibility checks per player","Before issuance","Skip any that fail","Customer Approaching File"],["11","Check SW x 40%, match the highest eligible ladder tier","Before issuance","Max = SW x 40%","BO, bonus ladder"],["12","Submit Lark ticket (query `VVIP TOP P&L BONUS`) with conversation screenshot, username, bonus amount","On issuance","Complete all ticket fields","Lark Base"],["13","Tick Claimed after submitting","After ticket","Mark status","Lark Base"],["14","Send Internal Message and Push to the player","After claim","Double-check content","BO"],["15","On claim: verify on list, verify amount, process","On player claim","Verify before processing","BO"],["16","Update the QA Record","After recording and issuance","Attach BO screenshots","Lark Base"]]},{"t":"h2","x":"7. Procedure: Zyra Platform (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Go to Betting Record > User Betting Record Overview","Task start","Correct BO path","Zyra BO"],["2","Report Date: Today; Export Daily Data","After opening","Save to the folder","Zyra BO"],["3","Open CS SORTING FILE, paste into the correct brand tab","After export","Correct brand tab","CS SORTING FILE"],["4","Sort Total P&L A to Z","After paste","Biggest losses at top","CS SORTING FILE"],["5","Open Customer Approaching File > Top 10 P&L (Night)","After sort","Correct section","Customer Approaching File"],["6","Filter to Tier 3 and Tier V only","After opening","Remove other tiers","Customer Approaching File"],["7","Copy and paste the top 10 qualifying players","After filtering","Top 10 only","Customer Approaching File"],["8","Run the eligibility checks per player","Before issuance","Skip any that fail","Customer Approaching File"],["9","Check SW x 40%; find last-7-day P&L: User Betting Record > Search UID > Last 7 days > (Deposit minus Withdraw); proceed only if negative","Before issuance","Proceed only if negative","Zyra BO"],["10","Match the highest eligible ladder tier","Before issuance","Max = SW x 40%","Bonus ladder"],["11","Submit Lark ticket (query `VVIP TOP P&L BONUS`) with conversation screenshot, UID, bonus amount","On issuance","Complete all ticket fields","Lark Base"],["12","Tick Claimed","After ticket","Mark status","Lark Base"],["13","Send Internal Message and Push","After claim","Double-check content","Zyra BO"],["14","On claim: verify on list, verify amount, process","On player claim","Verify before processing","Zyra BO"],["15","Update the QA Record","After recording and issuance","Attach BO screenshots","Lark Base"]]},{"t":"h2","x":"8. Guards"},{"t":"list","x":["SW x 40% is the absolute hard cap; a bonus above it cannot be issued.","If monthly P&L is profitable, the bonus cannot be issued, even on a daily loss.","Do not export before the data has fully loaded."]},{"t":"h2","x":"9. Remarks"},{"t":"list","x":["Night shift only.","TC: filter to VVIP before sorting. Zyra: filter to Tier 3 and Tier V.","Always check monthly P&L direction before issuing."]}]', '["C9MYR-RTN-SOP-N01","V1.1","Night Shift / Reporting + Compensation","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'loss compensation night bonus pnl p&l biggest loser', 17);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('top-deposit', 'SOP Book', 'Engagement Outreach', 'Top Deposit', '[{"t":"p","x":"**Applies to:** VIP CS, all brands"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Identify the top 20 winning depositors and engage them with VIP care. No bonus issuance, engagement only."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Night shift, daily at 8:30 PM. Target the top 20 players with positive P&L (winning) only. Losing players are covered under Top PNL and LTV."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Target positive P&L only (player winning). Losing players are skipped, handled under Top PNL.","No bonus messaging. No SMS. Channels: Internal Message + Push, sent simultaneously.","Focus is VIP care, interaction and relationship, not sales.","If fewer than 20 winners, fill down the ranking to 20.","Assess each player: highly active, long-term contributor, any recent churn signs."]},{"t":"h2","x":"4. Procedure: TC Gaming Platform (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Go to Report Management > Player Analysis","Task start","Re-use the Top 10 P&L export if available","TC Gaming BO"],["2","Select today''s date, confirm it displays","After opening","Today''s date only","TC Gaming BO"],["3","Search and wait for full load","Before export","Full load first","TC Gaming BO"],["4","Export the Excel report","After full load","Save to the folder","TC Gaming BO"],["5","Open CS SORTING FILE, paste into the correct brand sheet","After export","Tick only Username, Member Label, Deposit, Withdraw, Total P&L","CS SORTING FILE"],["6","Sort Deposit Amount Z to A","After paste","Highest depositors at top","CS SORTING FILE"],["7","Filter > By Condition > Total Player Win/Loss > Greater than > 0","After sort","Keeps winners only","CS SORTING FILE"],["8","Add a Tier header, filter to Tier 3 and Tier V only","After filtering","Remove other tiers","CS SORTING FILE"],["9","Copy the top 20 usernames","After filtering","Top 20 only","CS SORTING FILE"],["10","Paste into Customer Approaching File > TOP 20 Depositor (Night), correct brand","After copy","Correct brand column","Customer Approaching File"],["11","Send Internal Message + Push simultaneously: greeting, interaction, VIP care, no bonus","On send","Double-check content; no bonus","BO"],["12","Engage via Livechat or Telegram if they respond; tag `Deposit Engaged`","On response","Correct tag","Livechat / Telegram"],["13","Update the QA Record","After engagement","Attach a screenshot","Lark Base"]]},{"t":"h2","x":"5. Procedure: Zyra Platform (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Go to Betting Record > User Betting Record Overview","Task start","Correct BO path","Zyra BO"],["2","Report Date: Today; Export Daily Data","After opening","Export only UID, Deposit, Withdraw, Total Win/Loss","Zyra BO"],["3","Open CS SORTING FILE, paste into the correct brand tab","After export","Correct brand tab","CS SORTING FILE"],["4","Sort Deposit Amount Z to A","After paste","Highest depositors at top","CS SORTING FILE"],["5","Filter Total Win/Loss > Greater than > 0","After sort","Skip if filtered before download","CS SORTING FILE"],["6","Filter to Tier 3 and Tier V, keep top 20","After filtering","Top 20 only","CS SORTING FILE"],["7","Paste the top 20 UIDs into Customer Approaching File > TOP 20 Depositor (Night)","After copy","Correct section","Customer Approaching File"],["8","Send Internal Message + Push simultaneously: greeting, interaction, VIP care, no bonus","On send","No bonus","Zyra BO"],["9","Engage via Livechat or Telegram if they respond; tag `Deposit Engaged`","On response","Record any rare bonus exception","Livechat / Telegram"],["10","Update the QA Record","After engagement","Attach a screenshot","Lark Base"]]},{"t":"h2","x":"6. Guards"},{"t":"list","x":["Engagement only, no bonus. Losing players are excluded (handled under Top PNL and LTV) to avoid over-engagement.","If a winning player raises a complaint during engagement, handle it via the Complaint Handling SOP, not Top Deposit logic."]},{"t":"h2","x":"7. Remarks"},{"t":"list","x":["Relationship reinforcement and VIP care, not sales.","TC: filter to VVIP / Tier 3 and V. Zyra: filter to Tier 3 and Tier V."]}]', '["C9MYR-RTN-SOP-N02","V1.1","Night Shift / Reporting + Engagement","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'winner depositor vip care night engagement no bonus', 18);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('vvip-blast', 'SOP Book', 'Engagement Outreach', 'VVIP Blast', '[{"t":"p","x":"**Applies to:** VIP CS, all brands"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Notify newly upgraded VVIP players via Internal Mail to activate early engagement and welcome them to their new tier."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Morning shift only, daily at 3:00 PM. The newly upgraded VVIP player list is updated daily at 2:00 PM by ATL or above."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Do not send until the upgraded VVIP list is confirmed by ATL or above. The list updates at 2:00 PM.","Morning shift only; send at 3:00 PM.","Use the New Players template only. Never a template from another campaign type.","The goal is recognition, not pressure. No hard-sell, no urgency."]},{"t":"h2","x":"4. Procedure (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Confirm the upgraded VVIP list is updated by ATL or above","Before proceeding, after the 2:00 PM update","Do not send until verified","Team Engagement File"],["2","Copy and save the New Welcome Players column","After confirmation","Use today''s latest list only","Team Engagement File"],["3","Get the IM subject and content from Template Tab > New Players","Before sending","Do not use a template from another campaign type","Team Engagement File"],["4","Send IM to all newly upgraded VVIP players","At 3:00 PM (morning shift)","Verify segment and brand per player; use the correct template","BO (TC/Zyra)"],["5","Update the QA Record","After all IM is sent","Attach a BO screenshot","Lark Base"]]},{"t":"h2","x":"5. Messaging Principles"},{"t":"list","x":["Welcome and orientation: congratulate the player on the tier upgrade.","Introduce the VIP CS as the player''s PIC.","Explain what VIP support helps with: priority chat, dedicated assistance, fast issue resolution.","Explain how to contact the VIP CS: Live Chat, Telegram.","Optional: invite preferences (language, contact time, game preferences).","Avoid overselling, hard-sell language, urgency. The goal is recognition, not pressure."]},{"t":"h2","x":"6. Guards"},{"t":"list","x":["If the list is empty or not updated by 2:00 PM, notify the ATL immediately. Do not send an unconfirmed list.","Never send from an outdated or unconfirmed list.","Double-check segment and brand before sending, to avoid mismatched welcomes."]},{"t":"h2","x":"7. Remarks"},{"t":"list","x":["Morning shift only, after ATL or above confirms the updated list.","Always use the latest list, never an outdated one."]}]', '["C9MYR-RTN-SOP-D03","V1.1","Day Shift / VIP","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'welcome upgrade newly upgraded new vip tier', 19);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('internal-mail-approach', 'SOP Book', 'Engagement Outreach', 'Internal Mail Approach', '[{"t":"p","x":"**Applies to:** VIP CS, all brands"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Send targeted Internal Mail to players via the Back Office, based on brand, player segment and campaign direction."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Applies whenever Internal Mail is sent, on both TC and Zyra back offices. Zyra requires all three language versions."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Verify campaign type and recipient scope before sending. Sending to the wrong group cannot be undone.","Zyra: all three language versions (EN-MY, ZH-MY, MS-MY) must be filled before the message can be created.","Paste subject and content exactly from the approved template. Do not modify without TL approval.","Screenshot the confirmation screen immediately, as mandatory QA evidence."]},{"t":"h2","x":"4. Procedure: TC Gaming Back Office (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Go to Interact Management > Mail > Send Mail","Task start","Correct BO path","TC Gaming BO"],["2","Select the recipient type per campaign","After opening","Match the campaign direction","TC Gaming BO"],["2a","No specific group: select All User","When broadcasting","General broadcast","TC Gaming BO"],["2b","VIP only: select Specific Player Level","When tier-targeting","Tier-targeted","TC Gaming BO"],["3","Paste the Internal Mail subject","After recipient set","Exact from approved template","TC Gaming BO"],["4","Paste the Internal Mail content","After subject","Do not modify without TL approval","TC Gaming BO"],["5","Double-check brand, links, content, recipient","Before sending","All correct","TC Gaming BO"],["6","Click Send","On send","-","TC Gaming BO"],["7","Screenshot the confirmation screen immediately","Right after send","Mandatory QA evidence","TC Gaming BO"],["8","Update the QA Record","After screenshot","Attach the confirmation screenshot","Lark Base"]]},{"t":"h2","x":"5. Procedure: Zyra Back Office (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Go to Notification > System Messages","Task start","Correct BO path","Zyra BO"],["2","Click Add Message","After opening","-","Zyra BO"],["3","Select the recipient per campaign","After Add Message","Match the campaign direction","Zyra BO"],["3a","General: choose All User","When broadcasting","General broadcast","Zyra BO"],["3b","Targeted: choose the correct player group","When targeting","Correct group","Zyra BO"],["4","Fill EN-MY title and content","After recipient set","Exact from template","Zyra BO"],["5","Fill ZH-MY title and content","After EN-MY","Exact from template","Zyra BO"],["6","Fill MS-MY title and content","After ZH-MY","Exact from template","Zyra BO"],["7","Double-check recipient, brand, all language versions, content, links","Before creating","All three languages must be filled","Zyra BO"],["8","Click Create","On send","-","Zyra BO"],["9","Screenshot the confirmation screen immediately","Right after send","Mandatory QA evidence","Zyra BO"],["10","Update the QA Record","After screenshot","Attach the confirmation screenshot","Lark Base"]]},{"t":"h2","x":"6. Guards"},{"t":"list","x":["Sending to the wrong group cannot be undone; verify recipient scope before sending.","Zyra will not create the message until all three language versions are filled.","If a link or content error is found after sending, report it to your ATL or TL immediately."]},{"t":"h2","x":"7. Remarks"},{"t":"list","x":["Always screenshot immediately after sending, as mandatory QA evidence.","Zyra requires EN-MY, ZH-MY and MS-MY on every message."]}]', '["C9MYR-RTN-SOP-OUT01","V1.1","Outreach / Communication (All Shifts)","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'im blast back office mail tc zyra', 20);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('telegram-approach', 'SOP Book', 'Engagement Outreach', 'Telegram Approach', '[{"t":"p","x":"**Applies to:** VIP CS, all brands"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Engage selected VIP players through Telegram using a structured, priority-based approach. This SOP has three parts: the operational SOP, the engagement scripts, and the soft-skill playbook."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Telegram is a supplementary engagement channel. It does not replace Internal Mail or Livechat. Never promise, imply or hint at any bonus on Telegram."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Never promise, imply or hint at any bonus on Telegram.","Work strictly top down the priority order. Never approach a lower priority while higher-priority players are uncontacted.","One approach message per session. Wait for a reply before following up. Repeated messages get you blocked.","No VVIP or Priority Support language in Telegram drive content.","\"Available\" status is a last resort only, after all other approaches are exhausted. Ask the ATL."]},{"t":"h2","x":"4. Approach Priority Order"},{"t":"p","x":"Work strictly top down. Never approach a lower priority while higher-priority players are uncontacted."},{"t":"table","head":["Priority","Segment","Condition"],"rows":[["1","Churn","inactive 30 days"],["2","Churn","inactive 14 days"],["3","Churn","inactive 7 days"],["4","Churn","inactive 3 days"],["5","Churn","inactive 1 day"],["6","Grace Period","within grace window"],["7","High P&L","big win or loss today"],["8","LTV","loyalty selection"]]},{"t":"h2","x":"5. Procedure (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Open Customer Approaching File > Telegram section for the current month","Task start","Prior-month follow-ups: open the prior month''s file","Customer Approaching File"],["2","Review the priority list, identify the highest-priority players for this session","After opening","Start at Priority 1, work down","Customer Approaching File"],["3","For a Livechat referral or Friendly Player, create a record tagged accordingly","As encountered","Correct tag","Customer Approaching File"],["4","First approach: create a New Approach record with date, username, brand, tier, reason","On first contact","All fields filled","Customer Approaching File"],["5","Follow-up: add a sub-record under the original entry","On follow-up","Do not duplicate the entry","Customer Approaching File"],["6","Verify the player has a registered Telegram contact before approaching","Before sending","Registered contact confirmed","Telegram"],["7","Send the approach message with the right tone for the segment","On send","One message per session; wait for a reply before follow-up","Telegram"],["8","Record the outcome immediately","Right after send","Response Received, No Response, Deposit Made, or Referred to Livechat","Customer Approaching File"],["9","If they respond via Livechat after Telegram, record a successful Livechat conversion and link the reference","On Livechat response","Link the reference","Customer Approaching File"],["10","Update the QA Record at end of shift","End of shift","Total approached and conversion count","Lark Base"]]},{"t":"h2","x":"6. Engagement Scenarios"},{"t":"table","head":["Scenario","CS Objective"],"rows":[["Risk Player","Get a reply, learn the reason for inactivity, fix one issue, record preferences."],["Newly Upgraded VVIP","Establish the relationship, get consent for contact style, capture preferences, set expectation that VIP CS is useful."],["High-Loss Player","Welfare check. Support options, reduce pressure, protect the relationship. Not to drive activity."],["High Deposit / LTV","White-glove care, reinforce trust, improve service, without pushing bigger deposits."]]},{"t":"h2","x":"7. Timing Guardrails"},{"t":"list","x":["Newly Upgraded VVIP: soon after the 2:00 PM list update, in normal service hours.","Risk Player: same day the inactivity tier is first detected.","High-Loss Player: wait until at least the next day. Never message while emotions are high.","High Deposit / LTV: weekly, or scheduled relationship check-ins."]},{"t":"h2","x":"8. Soft-Skill Playbook (Part C)"},{"t":"steps","x":["Understand the starting point. Promo-claim players think \"no reason to stay\". Shift that to \"someone takes care of me here\".","First touch: start a conversation, do not jump into another promo.","Branch on response. Won: celebrate, soft-guide. Lost: acknowledge, reframe, never \"win it back\". No response: soft re-engagement later, no spam.","Become a personal assistant: recommend games at their level, respond fast, remember preferences.","Introduce value slowly, not just bonuses.","Micro-engagement builds habit. Consistency beats intensity.","Tag and personalise: preferred games, win-loss reaction, activity timing, deposit behaviour.","Avoid: messaging only when there is a promo, copy-paste spam, pushing deposits early, ignoring replies.","The goal is not \"get deposit\". It is to make the player feel guided, valued and comfortable. Deposits follow."]},{"t":"h2","x":"9. Guards"},{"t":"list","x":["Follow the priority order strictly; do not skip to a lower priority while higher ones are uncontacted.","One approach message per session; repeated messages get you blocked.","Never promise or hint at a bonus on Telegram."]},{"t":"h2","x":"10. Remarks"},{"t":"list","x":["Engagement scoring and the Kanban tracker are in the Telegram Engagement Tracker SOP.","\"Available\" status is a last resort only, after all other approaches are exhausted. Ask the ATL."]}]', '["C9MYR-RTN-SOP-OUT02","V1.1","Outreach / Communication (All Shifts)","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'telegram churn priority scripts soft skill outreach', 21);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('tg-engagement-tracker', 'SOP Book', 'Engagement Outreach', 'TG Engagement Tracker', '[{"t":"p","x":"**Applies to:** VIP CS and RTN Leaders"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Record, score and report Telegram engagement with churned and at-risk VIP players, through an automated Lark Base workflow. Read alongside the Telegram Approach SOP: that covers how to engage, this covers how it is tracked."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Tracks previously unrecorded KPI components: engagement rate, follow-up rate, reactivated churn count, CS engagement performance, RTN team productivity. This SOP is the tracker specification; it has no per-step procedure of its own, the engagement steps live in the Telegram Approach SOP."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Never delete records. Use an archival status.","All status changes via Kanban drag. No direct edits to the Score Table.","The Report Table is the only official KPI source. If figures look wrong, escalate to the ATL; do not recalculate manually.","Refresh the P&L Table daily, or new players never enter the workflow and levels go stale."]},{"t":"h2","x":"4. Roles"},{"t":"list","x":["**RTN Leaders (ATL / TL):** identify target churn players, add them to the Player List, monitor progress, review reports. Edit + config access.","**CS:** conduct engagement, update player status by Kanban drag, record engagement quality. Edit access."]},{"t":"h2","x":"5. Status Flow (Kanban)"},{"t":"p","x":"CS drags player cards across four columns. Each move fires an automation that writes to the Score Table."},{"t":"p","x":"`New` (default) -> `On Going Engagement` (CS starts contact) -> `Follow Up` (more nurturing needed) -> `Successful` (reactivated and deposits)."},{"t":"h2","x":"6. Engagement Quality Classification"},{"t":"p","x":"The single source of truth for engagement quality across the Handbook."},{"t":"table","head":["Level","Requirement"],"rows":[["HIGH","at least 10 meaningful replies"],["MEDIUM","roughly 3 to 5 meaningful replies"],["LOW","one reply, an emoji, or nothing"]]},{"t":"h2","x":"7. Player Level (auto from days since last deposit)"},{"t":"p","x":"Used for KPI scoring. Separate from the Telegram Approach priority tiers (which decide who to approach first)."},{"t":"table","head":["Level","Inactivity","Difficulty weight"],"rows":[["0","1 day","none"],["1","2 to 3 days","1.0x"],["2","4 to 7 days","1.5x"],["3","8 days and above","2.0x"]]},{"t":"h2","x":"8. KPI Formulas"},{"t":"code","x":"Contact Rate     = (Total Engagement / VIP Base) x 15      max 0.15\nFollow Up Rate   = (Total Follow Up / Total Engagement) x 10   max 0.10\nEngagement Score = Contact Rate + Follow Up Rate           max 0.25\nTotal Follow Up  = Grand Total Engagement - Total Engagement"},{"t":"p","x":"VIP Base = count of players with a Telegram link. Total Engagement = unique username/UID per PIC per brand."},{"t":"h2","x":"9. Reactivation Measurement"},{"t":"p","x":"Official reactivation counts use month-end P&L only. Real-time reactivation is not available; a successful engagement can happen before the official Reactivated flag appears. The Report Table is the final source."},{"t":"h2","x":"10. Common Mistakes (Guards)"},{"t":"table","head":["Mistake","Impact","Severity"],"rows":[["Contacted but status still New","engagement not recorded","High"],["Engaged repeatedly without status update","Follow Up KPI inaccurate","Medium"],["Wrong PIC assigned","score credited to the wrong person","High"],["Player deleted from workflow","historical record lost","Critical"]]},{"t":"h2","x":"11. Remarks"},{"t":"list","x":["Never delete records; use an archival status.","The Report Table is the only official KPI source. Escalate anomalies to the ATL, do not recalculate manually."]}]', '["C9MYR-RTN-SOP-OUT03","V1.1","Outreach / Communication (All Shifts)","Owner: ATL","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'telegram kanban score kpi reactivation tracker lark base', 22);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('sms-script', 'SOP Book', 'Engagement Outreach', 'SMS Script', '[{"t":"p","x":"**Applies to:** VIP CS (list preparation only)"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Prepare and maintain the SMS player list and content in the Team Engagement File. SMS sending is performed by the Retention Team Admin; VIP CS is responsible for list preparation only."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"VIP CS prepares the SMS player list in the Team Engagement File. Retention Team Admin retrieves and sends the SMS via the SMS platform. VIP CS is NOT responsible for the sending action."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["VIP CS responsibility ends at list preparation. SMS sending is done by Retention Team Admin.","SMS house rules: no em dashes, keep the Cari tag spacing exact, under 160 characters.","Never send expired content. Verify the expiration date before saving.","Correct segmentation matters. A mismatched segment approaches the wrong player and causes reporting errors."]},{"t":"h2","x":"4. Procedure: List Preparation (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Open the Team Engagement File","Before any update","Use the latest version","Team Engagement File"],["2","Check the latest player segmentation","Before changes","Confirm segments are current","Team Engagement File"],["3","Update engagement data under the correct segment and category","During update","Mismatched segments cause wrong approach and reporting errors","Team Engagement File"],["4","Record player info under the correct date and section","During update","Not under a previous or future date","Team Engagement File"],["5","Check for duplicated or missing records","Before saving","Duplicates cause double-counting","Team Engagement File"],["6","If the promotion has a 3-day validity, update the expiration date","During update","Align expiration with the latest update date","Team Engagement File"],["7","Verify the expiration date is not lapsed","Before saving","Never send expired content","Team Engagement File"],["8","Double-check all entries before handing to Retention Team Admin","At handover","VIP CS scope ends at handover; Admin sends","Team Engagement File"]]},{"t":"h2","x":"5. Guards"},{"t":"list","x":["Never hand over expired content; verify the expiration date first.","Verify segmentation before handover. A wrong segment means the wrong player and a reporting error.","Remove duplicates before saving, to prevent double-counting."]},{"t":"h2","x":"6. Remarks"},{"t":"list","x":["VIP CS responsibility ENDS at list preparation. SMS sending is done by Retention Team Admin.","SMS house rules (content standards): no em dashes, exact Cari tag spacing, under 160 characters."]}]', '["C9MYR-RTN-SOP-D05","V1.1","Day Shift / Communication","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'sms list preparation admin blast', 23);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('push-notification', 'SOP Book', 'Engagement Outreach', 'Push Notification', NULL, NULL, 'V1.0', 'ATL', 0, 'planned', NULL, 24);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('risk', 'SOP Book', 'Engagement Outreach', 'Risk Push', '[{"t":"p","x":"**Applies to:** VIP CS, all brands"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Send tier-graduated Push Notifications and Internal Messages to inactive players, to re-engage them before the risk level escalates."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Applies to inactive players by days-since-last-deposit tier (1D, 3D, 7D, 14D, 30D), on both TC and Zyra platforms. This SOP owns the risk-tier segmentation and messaging. The send mechanics are the shared ones in the Push Notification SOP (34)."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["TC uploads as `.txt`, Zyra uploads as `.csv` from the BO. Wrong format fails the upload.","1D is Push only (soft reminder, no urgency, no SMS, no IM). 3D and above add SMS + Internal Message.","Player must be inactive AND not already have claimed a similar bonus this cycle.","State clearly: the offer applies to the next deposit, has a validity period, and needs 1x turnover.","SMS is sent by Retention Team Admin; VIP CS prepares the list only.","RG / chase flag beats every push. Flagged players route to welfare, no push."]},{"t":"h2","x":"4. Risk Segmentation and Messaging Tiers"},{"t":"table","head":["Tier","Channels","Strategy"],"rows":[["1D, Soft Reminder","Push only","Light reminder, no urgency, no SMS, no IM"],["3D, Soft Emotional Pull","SMS + Internal Message","Emotional, personal appeal"],["7D, Strong Incentive","SMS + Internal Message","Reload bonus %, 1x turnover, limited time"],["14D, Strong Incentive","SMS + Internal Message","As 7D, higher bonus at TL discretion"],["30D, Strong Incentive","SMS + Internal Message","As 7D, highest-tier reactivation push"]]},{"t":"h2","x":"5. Bonus Logic"},{"t":"list","x":["Eligibility: player must be inactive AND not already claimed a similar bonus this cycle.","**TC BO:** bonus is auto / system-triggered; player claims directly in the app or website.","**Zyra BO:** bonus is manual; player contacts Live Chat, VIP CS states the offer, applies to next deposit. If already deposited, credit manually via Lark ticket.","Communication control: state clearly the bonus applies to the next deposit, has a validity period, and needs 1x turnover.","Tag `Risk 1D / 3D / 7D / 14D / 30D`, then `Reactivated` on deposit.","Record contact time, response, and conversion."]},{"t":"h2","x":"6. Procedure: TC Gaming Platform (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Open Team Engagement File, correct brand''s Risk Players column for the tier being sent (e.g. 1D)","Task start","Correct brand tab","Team Engagement File"],["2","Copy the Risk Player database, save as `.txt`","After locating","TC requires `.txt`","Team Engagement File"],["3","Get Push subject and content from Template Tab > Risk Player","Before send","Do not modify without TL approval","Team Engagement File"],["4","Go to Interact Management > Mail > Push Notification > Send Notification","Ready to send","Correct BO path","TC Gaming BO"],["5","Select Specific User > Firebase App Messaging, upload the `.txt`","On send","Verify file format","TC Gaming BO"],["6","Input subject and content, click OK","On send","Double-check all fields","TC Gaming BO"],["7","Update the QA Record","After send","Attach a BO screenshot","Lark Base"]]},{"t":"h2","x":"7. Procedure: Zyra Platform (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Open Team Engagement File, correct brand''s Risk Players column for the tier being sent (e.g. 1D)","Task start","Correct brand tab","Team Engagement File"],["2","Copy the database, export as `.csv` from the BO","After locating","Zyra requires `.csv`, not `.txt`","Zyra BO"],["3","Get Push subject and content from Template Tab > Risk Player","Before send","Approved copy only","Team Engagement File"],["4","Go to Notification > Push Notification > Add Push Notification","Ready to send","Correct BO path","Zyra BO"],["5","Target Type: User; upload `.csv`, input subject and content, click Create","On send","Verify the correct player group","Zyra BO"],["6","Update the QA Record","After send","Attach a BO screenshot","Lark Base"]]},{"t":"h2","x":"8. Guards"},{"t":"list","x":["Wrong file format fails the upload: verify TC `.txt` / Zyra `.csv` every time.","If the Risk Player list is empty, record it in the QA Record and inform the ATL.","RG / chase flag: no push at all, route to welfare."]},{"t":"h2","x":"9. Remarks"},{"t":"list","x":["For 3D, 7D, 14D, 30D tiers, SMS is also sent. SMS is handled by Retention Team Admin; VIP CS prepares the list only.","Send mechanics match the Push Notification SOP (34); this SOP owns the risk-tier logic."]}]', '["C9MYR-RTN-SOP-D04","V1.1","Day Shift / Communication","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'inactive churn push reactivate 1d 3d 7d 14d 30d reload notification', 25);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('reactivation-win-back', 'SOP Book', 'Engagement Outreach', 'Reactivation & Win-back', NULL, NULL, 'V1.0', 'ATL', 0, 'planned', NULL, 26);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('special-event-campaign', 'SOP Book', 'Engagement Outreach', 'Special Event Campaign', NULL, NULL, 'V1.0', 'ATL', 0, 'planned', NULL, 27);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('complaint-handling', 'SOP Book', 'Service & Exceptions', 'Complaint Handling', '[{"t":"p","x":"**Applies to:** All VIP CS"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Handle common Livechat complaint scenarios with empathy and strategy. Combine emotional acknowledgement with a strategic response."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Applies to losing-player and free-credit complaint scenarios on Livechat. Always acknowledge the emotion before moving to a solution."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Always acknowledge the emotion before moving to a solution or redirection.","Never promise a bonus you cannot deliver. If unsure, say \"let me check\", never a false commitment.","Use Secret Wallet credit only where the scenario qualifies; size by tier (T3 = 3%, TV = 5%) and remaining monthly allowance.","For the formal compensation decision, use the Compensation SOP; for amounts and tier rules, the Bonus rules."]},{"t":"h2","x":"4. Complaint Scenarios and Responses"},{"t":"table","head":["Complaint","What you see in profile","Recommended response","Strategy"],"rows":[["Losing a lot","Significant losses this week, SW has balance, no recent credits","\"Saya nampak boss memang rugi sikit hari ni. Saya bagi sikit credit untuk boss try balik.\"","Always use Secret Wallet credit here. Base the amount on tier (T3 = 3%, TV = 5%) and remaining monthly allowance."],["Losing little","Small losses, not enough for SW credit","Step 1 acknowledge: \"Boss faham tu, memang kadang rasa macam tak kena.\" Step 2 game suggestion. Step 3 reframe toward hope.","Validate the feeling without committing a credit. Offer a fresh game. Reframe losses as timing, not bad luck."],["Always asks for free credit","Habitual requests, no qualifying condition","Decline gently: \"Boss hari ni belum ada free credit lagi ye.\" Redirect to a game. Promise future notification by SMS.","Redirect without rejection. The player should leave feeling looked after even without getting what they asked."]]},{"t":"h2","x":"5. Procedure (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Acknowledge the emotion first","On complaint open","Validate the feeling before any solution or redirect","Livechat"],["2","Read the player profile","Before responding","Check losses, SW balance, recent credits, risk/abuse tag","BO"],["3","Match the scenario and respond","After assessment","Per Section 4; SW credit only where the scenario allows, sized by tier % and remaining allowance","Livechat, Bonus rules"],["4","Log the outcome","After handling","QA Record; if compensation was issued, Lark ticket (query `VVIP Complain player`)","Lark Base"]]},{"t":"h2","x":"6. Building Relationships Through Complaint Moments"},{"t":"list","x":["Malaysian events and holidays: chat about festivities, long weekends, public holidays.","Food and local culture: a universal opener. Ask about favourite dishes, hawker stalls, lunch.","Game discussions: games they enjoy, new titles, jackpot stories, recent wins.","Use complaint moments to listen and learn. Every complaint is data about the player''s preferences and pain points."]},{"t":"h2","x":"7. Guards"},{"t":"list","x":["No false commitment: if you cannot confirm a credit, say \"let me check\" first.","SW credit only when the scenario and remaining allowance permit.","Emotion first, solution second; skipping the acknowledgement loses the relationship."]},{"t":"h2","x":"8. Remarks"},{"t":"list","x":["For the formal compensation decision logic, refer to the Compensation SOP.","For Angpao / Free Credit / Reload amounts and tier rules, refer to the Bonus rules."]}]', '["C9MYR-RTN-SOP-CHAT02","V1.1","Soft Skill / Engagement","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'complaint livechat empathy credit angry losing', 28);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('chat-sop', 'SOP Book', 'Service & Exceptions', 'Chat SOP', '[{"t":"p","x":"**Applies to:** All VIP CS"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"A comprehensive case-handling library. Each row is a scenario with step-by-step actions across four stages: Get Details, Verify / Check, Action / Submit, Notify / Close."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Applies to all Livechat case handling. Navigate by category. Always tag the chat correctly (see Tags & Categories) and close with an offer of further assistance plus a good-luck wish."},{"t":"callout","tone":"info","x":"Format note: this SOP is a scenario library. Its four stage columns (Get Details, Verify / Check, Action / Submit, Notify / Close) are this library''s form of the 4-element step: the Action is the stage entry, the Sequence is the left-to-right stage order, the Degree / standard is the check condition in each cell, and the Tool is the BO / Lark ticket named in the cell. The columns are kept as-is rather than split per scenario."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Always close with an offer of further assistance plus a good-luck wish.","Always tag the chat correctly (see Tags & Categories).","When escalating to WL, Support, IT or PYM, always include Username/UID, amount and screenshots.","After submitting any ticket, tick the Claimed checkbox in the relevant tracker.","Run a fresh identity verification every chat; never rely on a previous one."]},{"t":"h2","x":"4. Registration"},{"t":"table","head":["Scenario","Get Details","Verify / Check","Action / Submit","Notify / Close"],"rows":[["Unable to Register","Username / phone / email, screenshot of error","Check BO if phone/email already used. Validate the phone via messente.com/phone-validator","Duplicate: advise accordingly. Technical: escalate to WL / IT support.","Offer further assistance, close with wishes."]]},{"t":"h2","x":"5. Account"},{"t":"table","head":["Scenario","Get Details","Verify / Check","Action / Submit","Notify / Close"],"rows":[["Delete Game Account","Ask the reason","Deletion is not permitted. Find the true intent.","Persuade and console. Offer high-pay games as an alternative.","Offer further assistance, close."],["OTP Failed (TC BO)","Phone, telco","Validate phone. BO > Player Management > SMS Sent Record. Check if requested and the count (5 reached, go to close).","Ask member to click Get Code again. Provide manual OTP: SMS Sent Record > Search By Verification > input number without 0 > copy OTP. Check expiry.","If it keeps failing, advise retry after 12am. Report to senior."],["OTP Failed (96 BO)","Phone, telco","Validate phone. BO > User > User TAC > input number > Search. Check if requested and count.","Ask member to Resend OTP. Provide manual OTP from User TAC. Check expiry.","If it keeps failing, retry after 12am. Report to senior."],["Forgot Password","Send reset template","No OTP: go to OTP Failed SOP. Other: get username, full name, bank details, phone, then verify.","Pass: reset random password (Name+TodayDate). Fail: use the fallback options per detail matched.","Advise to change password after login. New verification every chat, never rely on a previous one."],["Forgot Password (OTP over daily limit)","Username, full name, bank details, phone","Verify details","Pass: reset random password (Name+TodayDate). Fail: reset password to SMS.","Advise change after login. Educate on self-service reset."],["Forgot PIN / Reset PIN (EZ96 & BM69)","Send PIN reset template","If reset fails: UID, full name, bank details, KYC verify","KYC verified: reset PIN.","Notify member. New verification every chat."],["Change Phone Number","Username/UID, name, registered phone, reason; then new phone, telco, screenshot of new number","Check if the new number is already registered. Used: duplicate account SOP. Unused: proceed.","Submit Lark ticket CS-PYM-v3, tier level, query OTHERS (FOR CS CBD), remark full name / old / new number.","Compliance amends, agent rechecks, notify. Ticket to CS TEAM SOLVED."]]},{"t":"h2","x":"6. Bank"},{"t":"table","head":["Scenario","Get Details","Verify / Check","Action / Submit","Notify / Close"],"rows":[["Remove Bank Details (not duplicate)","Username/UID, reason","No valid reason to remove","Advise we cannot remove bank details.","Close with wishes."],["Change Bank (TC BO)","Username, reason; then correct bank details","Verify with payment team in Lark. Check BO for duplicate. TNG: send DuitNow ID guide.","Submit CS-PYM, query Others, remark bank to delete / keep.","Inform member to refresh. Ticket to CS TEAM SOLVED."],["Change Bank (Zyra BO)","UID, reason","TNG profile (name + DuitNow ID) or bank statement. KYC mandatory. Check duplicate.","Submit CS-PYM, remark bank to delete / keep.","Inform member to refresh."],["Unable to WD, invalid bank (WD disabled)","Username/UID, TNG or bank statement, KYC","Check BO for duplicate with new bank","Advise add correct bank first (TC BO). Submit CS-PYM, remark valid bank / reactivate WD.","Inform member to refresh and submit WD. Seniors send internal message re WD reject."]]},{"t":"h2","x":"7. Withdraw"},{"t":"table","head":["Scenario","Get Details","Verify / Check","Action / Submit","Notify / Close"],"rows":[["Unable to Withdraw, turnover not met","Username/UID, error screenshot","Check BO Turnover Checking","Advise to complete required TO in the correct game.","Close with wishes."],["WD Rejected, duplicated","Username/UID","Check BO remarks. Search MYR CMP Duplicate User Record.","Advise per findings: duplicate account, winnings forfeited.","Close."],["WD Rejected, invalid account","Username/UID","Check BO Withdraw ID. Search rejection in C9MYR CS-RISK-PYM group.","Advise reason. Get amendment (TNG / bank statement, KYC). Check duplicate. Submit CS-PYM, remark valid bank / reactivate WD.","Compliance amends, agent rechecks, notify."],["WD Double","Username, transaction history screenshot","Check BO Withdrawal Record","Inform member they were randomly selected for a surprise bonus.","Close."],["WD Missing (approved, not received)","Username/UID, amount","Check BO Withdrawal Record","Submit CS-PYM, query Missing WD.","If released, confirm and send receipt. If not, follow PYM, advise wait 2-3 days."],["Delayed WD / follow-up","Username/UID","Ask member to wait. Check BO. If delayed over 10 min, escalate.","Submit CS-PYM, query WD Delay. Follow if still over 10 min.","On complete, recheck BO, notify."]]},{"t":"h2","x":"8. Deposit"},{"t":"table","head":["Scenario","Get Details","Verify / Check","Action / Submit","Notify / Close"],"rows":[["Deposit not credited","Username/UID, receipt","Verify in BO","Submit CS-PYM, tier level.","Close."],["Friend''s account to deposit","Member asks about 3rd-party","3rd-party deposits not allowed","Offer another solution.","Close."],["Reject deposit request (already transferred)","Username/UID, receipt","Follow up with PYM","Submit CS-PYM, tier level.","Close."],["Old QR / duplicate transfer","Username/UID, full name, receipt","Verify on BO, details match receipt","If match, submit CS-PYM, query DP Slip verification. PYM finds duplicate, member acknowledges.","Advise new deposit without transferring. Record new order ID, revert to PYM."],["Incorrect deposit amount","Username/UID, full name, receipt","Verify on BO. If mismatch, advise re-submit without transferring.","Member re-submits, submit CS-PYM, comment incorrect amount.","On approval, notify."],["Deposit below minimum","Username/UID, full name, receipt","Verify on BO, below RM 10 minimum. Advise top-up to reach it.","Member deposits difference, submit CS-PYM, comment combine deposit.","On approval, notify. Advise future deposits >= RM 10."],["Deposit from 3rd-party account","Request details","Verify in BO. If 3rd-party, cannot process. Request sender details for refund.","Member provides sender details, submit CS-PYM, tier level.","Refund to sender''s account only."],["Pre-approved Deposit (VIP)","Request details","PYM offers pre-approval agreement. Member agrees, follow daily, watch for bounce-back, get bank statement.","Follow up 7 days after pre-approval.","Close. Use the standard pre-approval message with its two conditions."]]},{"t":"h2","x":"9. Fund"},{"t":"table","head":["Scenario","Get Details","Verify / Check","Action / Submit","Notify / Close"],"rows":[["Fund Missing / Game Maintenance","Username/UID, amount, last game","Access via test account, then another site. Check TG maintenance group.","If no notice, escalate to WL / Support.","Advise game under maintenance, credit auto-refunds after."],["Unable to Access Game","Username/UID, last game","Access via test account and another site. Check TG maintenance.","If no maintenance, escalate to WL / Support.","Advise unstable / maintenance, suggest alternatives."],["Game not under maintenance (TC BO)","Username/UID, amount, game","Access via test account, confirm normal with WL","Escalate to WL. Then BO > Player Transfer Exception > Rollback Action. If present, rollback, ask member to refresh.","Recheck funds returned, notify."],["Game not under maintenance (EZ BO)","Username/UID, amount, game","Access via test account, confirm with WL. WL requests fund transfer back.","Submit CS-PYM, query Others, include WL screenshot.","Compliance completes, agent rechecks, notify."]]},{"t":"h2","x":"10. Others"},{"t":"table","head":["Scenario","Get Details","Verify / Check","Action / Submit","Notify / Close"],"rows":[["DP / WD under PG maintenance","Username/UID, full name, receipt or amount","Verify on BO, details match","Submit CS-PYM, tier level. Advise member to wait, we monitor.","On completion, approve, notify."],["Technical issue, cannot access game","Username/UID, full name, game / screenshot","Identify issue. If live, send to WL / Support.","Receive IT result.","If resolved, ask member to verify. If not, advise will be notified."],["Technical issue, missing fund","Username/UID, full name, amount, game / screenshot","Identify issue. Send to WL / Support.","Receive IT/WL result.","If resolved, verify. If not, advise will be notified."],["Unsubscribe SMS Promo","Username/UID, phone, reason","Advise the benefits, recommend other promos","If member insists, post in VIP group and tag the designated admin to remove.","Close."],["Unsubscribe Push Notification","Username/UID, reason","Send template, assure of benefits","If member insists, post in VIP group and tag the designated admin to remove.","Close."]]},{"t":"h2","x":"11. Guards"},{"t":"list","x":["Do not delete a game account or remove bank details without a valid, verified reason; both are not permitted by default.","Never process a 3rd-party deposit; refund only to the sender''s account.","Escalations to WL / Support / IT / PYM must carry Username/UID, amount and screenshots, or they bounce back.","Run a fresh identity verification every chat before any reset."]},{"t":"h2","x":"12. Remarks"},{"t":"list","x":["Always close with an offer of further assistance plus a good-luck wish.","Chinese-speaking members: use ChatGPT, or transfer to a Chinese-speaking CS for complex cases.","Always tag the chat correctly, see Tags & Categories.","After submitting any ticket, tick the Claimed checkbox in the relevant tracker.","Names are omitted per house rule; \"designated admin\" is the routing role for unsubscribe requests."]}]', '["C9MYR-RTN-SOP-CHAT01","V1.1","Soft Skill / Chat","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'otp password withdraw bank register account case library troubleshoot', 29);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('checking-conversation-history', 'SOP Book', 'Service & Exceptions', 'Checking Conversation History', '[{"t":"p","x":"**Applies to:** All PIC / Agent handling VVIP players"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Deliver a personalised VVIP experience by requiring every CS staff member to review the player''s previous conversation history before engaging, across both LiveChat and Telegram."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Applies to all inbound and outbound VVIP contact, on every brand, in both directions of channel crossover."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Before replying to any VVIP player, review the Last Telegram Chat Link or Last LiveChat Link to understand the player''s history.","Review both LiveChat and Telegram history whenever both are available.","Never ask a player to repeat information they already provided."]},{"t":"h2","x":"4. Channel Crossover"},{"t":"p","x":"The key is channel crossover: a player rarely stays on one channel. Before replying, check the other channel too, so you have the full history."},{"t":"p","x":"**Scenario 1: Player arrives from LiveChat.** Before replying, open the player''s Last Telegram Chat Link and review their Telegram history as well, so nothing they raised on Telegram is missed."},{"t":"p","x":"**Scenario 2: Player arrives from Telegram.** Before replying, open the player''s Last LiveChat Link and review their LiveChat history as well, so nothing they raised on LiveChat is missed."},{"t":"callout","tone":"info","x":"The source doc illustrates each scenario with a screenshot guide showing where the Last Telegram Chat Link and Last LiveChat Link sit. Follow the on-screen guide for the exact click path."},{"t":"h2","x":"5. Procedure (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Identify the arrival channel","On contact","LiveChat or Telegram","Customer Approaching System"],["2","Open the player''s other-channel history before replying","Before the first reply","LiveChat arrival: open Last Telegram Chat Link. Telegram arrival: open Last LiveChat Link","LiveChat / Telegram"],["3","Review the full history","Before replying","Note unresolved issues and pending requests; never ask the player to repeat","Both channels"],["4","Update the player record after the interaction","After handling","Record the outcome and any follow-ups","Customer Approaching System"]]},{"t":"h2","x":"6. CS Responsibilities"},{"t":"steps","x":["Always check conversation history before contacting or replying to a player.","Review both LiveChat and Telegram history whenever both are available.","Never ask a player to repeat information already provided.","Follow up on unresolved issues and pending requests.","Update the player record after every interaction."]},{"t":"h2","x":"7. Expected Outcome"},{"t":"list","x":["Better VVIP customer experience","Consistent communication across all channels","Reduced repetitive questioning","Faster issue resolution","Improved player satisfaction and retention"]},{"t":"h2","x":"8. Remarks"},{"t":"list","x":["Follow the on-screen guide for the exact click path to each channel''s last-chat link.","The history check is required on every VVIP interaction, inbound or outbound."]}]', '["C9MYR-RTN-SOP-001","V1.1","Service Standard","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'conversation history vvip check', 30);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('zyra-forgot-password', 'SOP Book', 'Service & Exceptions', 'ZYRA Forgot Password', '[{"t":"p","x":"**Applies to:** All VIP CS, ZYRA brands"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Restore access for a ZYRA member who has forgotten their password, by verifying identity in full and issuing a random reset password."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Applies when a ZYRA member cannot log in or has forgotten their password and asks for help."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Verify all four identity items before any reset: UID, registered name, phone number (BO shows the last 4 digits), registered bank name and bank account number.","Perform a fresh verification each chat. Never rely on a previous verification.","The random password is temporary; the member must set their own after login."]},{"t":"h2","x":"4. Pre-Reset Verification (mandatory)"},{"t":"p","x":"Verify all of the following before any reset:"},{"t":"steps","x":["UID","Registered name","Phone number (the BO shows the last 4 digits for verification)","Registered bank name and bank account number"]},{"t":"p","x":"Make sure every item is verified correctly before proceeding. Perform a fresh verification each chat, never rely on a previous one."},{"t":"h2","x":"5. Procedure: Reset (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Reset the member''s password and generate the random reset password","After full verification","Only once all four identity items pass","Zyra BO"],["2","Provide the random password to the member","After reset","Temporary password only","Livechat"],["3","Ask the member to log in with the random password","After providing","Confirm a successful login","Livechat"],["4","Require the member to create their own new password","After successful login","Member sets their own password","Zyra app / site"]]},{"t":"h2","x":"6. Expected Outcome"},{"t":"p","x":"The member regains access, sets a new password of their own, and can use the account normally."},{"t":"h2","x":"7. Guards"},{"t":"list","x":["No reset without complete, fresh identity verification.","Never keep or reuse the temporary password; the member must replace it at first login."]},{"t":"h2","x":"8. Remarks"},{"t":"list","x":["Verification is mandatory and must be complete before resetting.","The random password is temporary; the member must set their own after login."]}]', '["C9MYR-RTN-SOP-003","V1.1","Technical / Account Support","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'password reset zyra forgot', 31);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('redeem-code-s0403', 'SOP Book', 'Service & Exceptions', 'Redeem Code S0403', '[{"t":"p","x":"**Applies to:** All VIP CS"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Standardise the verification sequence before a redeem code fault is escalated, so that only genuine system faults reach the Assistant Team Leader."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Applies when a player confirmed to be on the eligible list cannot redeem their assigned code and gets an \"Expired\" or \"Invalid\" (S0403) response."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["Complete all verification steps before escalating. The ATL step is for confirmed faults only.","Do not conclude a code is expired from the error alone; verify eligibility, the assigned code, status and claim first.","Escalate only when all four escalation criteria are confirmed."]},{"t":"h2","x":"4. Procedure: Verification (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Check the Redeem Code File","Task start","Open it in the Customer Approaching File, search the member''s Username or UID","Customer Approaching File"],["2","Verify customer information","After locating the record","UID correct, correct customer account, correct brand","Customer Approaching File / BO"],["3","Verify the redeem code","After customer info","The code the customer entered matches the code assigned in the system","Customer Approaching File"],["4","Check the Status field","After code check","Claimed: already claimed. Expired: check whether it has actually expired","Customer Approaching File"],["5","Check in BO","Before any escalation","Event > Redeem Code > Redeem Code Payout; enter the code; status \"approved\" means the member already claimed it","BO"]]},{"t":"h2","x":"5. Escalation Criteria"},{"t":"p","x":"Escalate to the ATL only when ALL of these are confirmed:"},{"t":"list","x":["Customer is eligible","Correct redeem code","Code is not claimed","System still shows S0403 / Invalid or Expired"]},{"t":"h2","x":"6. Escalation Template"},{"t":"p","x":"Provide all of the following to the ATL:"},{"t":"code","x":"UID: [uid]\nBrand: [brand]\nRedeem Code: [code entered]\nError: Invalid or Expired\nCode assigned in system: [assigned code]\nIssue: Customer is eligible and entered the assigned code, but the system\nstill returns an Invalid/Expired (S0403) error. Please assist to verify."},{"t":"h2","x":"7. Expected Outcome"},{"t":"p","x":"Most cases resolve at the CS step (wrong code, not eligible, or already claimed). Only a genuine S0403 fault, with everything else confirmed correct, reaches the ATL."},{"t":"h2","x":"8. Guards"},{"t":"list","x":["Complete all five verification steps before escalating.","Do not escalate on the error message alone; confirm eligibility, assigned code, status and claim first."]},{"t":"h2","x":"9. Remarks"},{"t":"list","x":["The ATL step is for confirmed faults only.","Most S0403 reports resolve at the CS verification step."]}]', '["C9MYR-RTN-SOP-002","V1.1","Technical / Account Support","Owner: VIP RTN","Updated 7 Sep 2026"]', 'V1.1', 'ATL', 0, 'live', 'redeem code s0403', 32);
insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('kpi-scoring', 'SOP Book', 'People & Operations', 'KPI Scoring', '[{"t":"p","x":"**Applies to:** ATL (scorer); Seniors and Juniors (scored)"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Score each agent''s monthly KPI the same way every time, from evidence, so the number reflects real performance and survives review by the SPV or Department Head."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Monthly KPI scoring for Team B, on the Senior and Junior scorecards. Weights and bands are the rubric; this SOP governs the scoring process, not the rubric design."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["**Change weights by rule, for everyone. Never edit a metric score to hit a target.** Lowering a correct score to reach a number is falsifying a record.","**Every score is evidence-backed.** No invented figures.","**One rubric per role.** The same weights and band cutoffs apply to all Seniors, and all Juniors.","**A raw on a threshold takes the band it meets, not the higher one.**"]},{"t":"h2","x":"4. Band Meaning (SPV)"},{"t":"table","head":["Score","Meaning"],"rows":[["60-65","No mistake, baseline"],["65-70","Slight improvement, still needs pointer"],["70-80","Improving on weakness, less pointer"],["80-90","Above expectation, self-improving"],["90-100","Near perfect, exceeds the role"]]},{"t":"h2","x":"5. Procedure (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Pull evidence per metric","Month-end, after close","Each metric from its named source; post-close data only","contact_log, QA sheet, LC report, mistake log, Lark"],["2","Score each metric to a band","After evidence","Map raw to 0/40/60/80/100 by the cutoffs; threshold takes the lower band","Scorecard bands"],["3","Apply the role weights","After scoring","Uniform weights for the role; weighted = weight x score","Scorecard"],["4","Sum and sense-check","After weighting","Total = sum of weighted; does it match the person''s real level (Section 4)?","Scorecard total"],["5","If the number feels wrong, fix the rubric, not the cell","On mismatch","Adjust weights/thresholds and re-run for everyone; never hand-lower one score","Rubric"],["6","Evidence-review any disputed metric","Before finalising","A score moves only if the evidence supports it (e.g. Reporting = 40 needs the logs)","Source logs"],["7","Record and release","After sign-off","Lock the sheet, note the weights version and date; brief the agent with the coaching 5-step","Scorecard, Lark"]]},{"t":"h2","x":"6. Over-Scoring Guards"},{"t":"list","x":["No score-tuning to a target; weights only, applied uniformly.","Every score evidence-backed; no invented figures.","The result must square with the band meaning in Section 4."]},{"t":"h2","x":"7. Remarks"},{"t":"list","x":["Current Senior scorecards use different weights per person; standardise to one Senior template and one Junior template.","The QA cutoff must be identical across people, or the metric is not comparable.","New staff on probation are scored for evaluation and coaching only. Entitlement to rev share / bonus / KPI incentive is gated on passing probation (see New Staff Incentive Eligibility SOP, 37)."]}]', '["C9MYR-RTN-SOP-PRF01","Performance / Reporting","Updated 5 Sep 2026"]', 'V1.0', 'ATL', 0, 'live', 'kpi frt discipline deposit growth retention target score', 33);
