insert or replace into sops (id, section, domain, title, body, meta, version, owner, restricted, status, keywords, sort) values ('incognito-browsing', 'SOP Book', 'Systems, Automation & Continuity', 'Incognito Browsing', '[{"t":"p","x":"**Applies to:** All staff, every shift"},{"t":"h2","x":"1. Objective"},{"t":"p","x":"Require every staff member to use Google Chrome in Incognito mode for all work during a shift, so no work logins, history, cookies or cache persist on the machine, and every session starts clean."},{"t":"h2","x":"2. Scope"},{"t":"p","x":"Every shift, every staff member. Covers any Chrome use for work: back office (BO), Lark and other work documents, and any website opened for a work task, on all brands. It does not change which sites you may access; it governs how Chrome is opened."},{"t":"h2","x":"3. Golden Rules"},{"t":"list","x":["All work use of Chrome is in Incognito: back office, documents, and any browsing. No exceptions during a shift.","Open Lark files by copying the file link and pasting it into the Incognito window, not through the Lark app or a normal browser.","Never use a normal (non-Incognito) Chrome window for work.","Never save or autofill work logins or passwords in Chrome.","Non-compliance is a disciplinary matter (see Section 5)."]},{"t":"h2","x":"4. Procedure (Action / Sequence / Degree / Tool)"},{"t":"table","head":["#","Action","Sequence (when)","Degree / standard","Tool"],"rows":[["1","Open Chrome in Incognito","Before any work browsing, at shift start","Ctrl+Shift+N, or Chrome menu > New Incognito window; confirm the dark Incognito window is active","Chrome"],["2","Log in to the BO in the Incognito window","Each BO session","Every back office opened inside the Incognito window; log in fresh, do not save the password","Chrome Incognito, BO"],["3","Open Lark files and work sites in Incognito","Throughout the shift","For a Lark file or doc: open it, copy its link, and paste the link into the Incognito window. Do not open it in the Lark app or a normal browser. Open any other work site directly in Incognito","Lark; Chrome Incognito"],["4","Keep no normal Chrome window for work","Throughout the shift","Do not use a regular (profile, history-saving) Chrome window for any work task","Chrome"],["5","Close the Incognito window at breaks and shift end","On break and at shift end","Close it so no session or cache persists on the machine","Chrome"],["6","Report if Incognito is blocked or unavailable","On any issue","Tell the ATL or TL at once; do not fall back to a normal window","Lark"]]},{"t":"h2","x":"5. Enforcement"},{"t":"table","head":["Instance","Consequence"],"rows":[["First non-compliance","Verbal warning"],["Repeat or continued non-compliance","Warning letter"]]},{"t":"p","x":"Issued through the department disciplinary process."},{"t":"callout","tone":"warn","title":"Pending confirmation","x":"Confirm with HR / Supervisor: the exact ladder, whether a further step follows a warning letter, and who issues each stage."},{"t":"h2","x":"6. Guards"},{"t":"list","x":["A back office or work document opened in a normal Chrome window is a violation, even once.","Do not let Chrome save or autofill work credentials.","If Incognito is disabled by IT or policy, report it and wait for guidance. Do not work around it in a normal window."]},{"t":"h2","x":"7. Remarks"},{"t":"list","x":["**Why:** Incognito keeps no history, cookies, cache or saved logins on the machine once the window closes, so work sessions and credentials do not persist on a shared or work device, and each shift starts with a fresh login.","**What it does not do:** Incognito does not make activity anonymous to the company, IT or the network. The purpose is local session and credential hygiene, not hiding activity.","Cross-reference: Attendance (Pre-Shift Setup) SOP, which includes opening Chrome in Incognito as a pre-shift step; Channel Login SOP for BO access."]}]', '["C9MYR-RTN-SOP-O03","V1.0","Operation / Security","Owner: ATL","Updated 9 Sep 2026"]', 'V1.0', 'ATL', 0, 'live', NULL, 41);
